          { g: "→", role: "frame", ref: "23:2b", src: "<span class=\"pmw-src\" data-lang=\"he\" dir=\"rtl\" lang=\"he\"><span class=\"pmw-w\" data-lang=\"he\" data-tip=\"nā&#x27;â · in pasture, abode, abode of shepherd\">בִּנְא֣וֹת</span> <span class=\"pmw-w\" data-lang=\"he\" data-tip=\"deše&#x27; · grass, new grass, green herb\">דֶּ֭שֶׁא</span> <span class=\"pmw-w\" data-lang=\"he\" data-tip=\"rāḇaṣ · to stretch oneself out, lie down, lie stretched out… me\">יַרְבִּיצֵ֑נִי</span> <span class=\"pmw-w\" data-lang=\"he\" data-tip=\"ʿal · preposition upon, on the ground of, according to\">עַל</span> <span class=\"pmw-w\" data-lang=\"he\" data-tip=\"mayim · water, waters water water of the feet, urine of…\">מֵ֖י</span> <span class=\"pmw-w\" data-lang=\"he\" data-tip=\"mᵊnûḥâ · resting place, rest resting place rest, quietness\">מְנֻח֣וֹת</span> <span class=\"pmw-w\" data-lang=\"he\" data-tip=\"nāhal · to lead, give rest, lead with care me\">יְנַהֲלֵֽנִי</span></span>", html: 'he leadeth me beside the still waters.' }
